import time
import cv2
import torch
from ultralytics import YOLO
from PIL import Image, ImageDraw

import os
# os.environ["CUDA_VISIBLE_DEVICES"] = "-1"

def crop_image_by_pixels(image, pixels, ):
    # 创建一个全黑的掩膜图像，与原始图像大小相同
    mask = np.zeros_like(image)
    # 将给定的像素点数组转换为整数类型的 NumPy 数组
    pixels = np.array(pixels, dtype=np.int32)
    # 使用多边形绘制填充区域
    cv2.fillPoly(mask, [pixels], (255, 255, 255))
    # 使用掩膜图像对原始图像进行分割
    segmented_image = cv2.bitwise_and(image, mask)
    return segmented_image
#MetadataCatalog.get(DATASET_STR).thing_colors = [(255, 0, 255), (47, 255, 173), (255, 255, 0), (71, 99, 255), (205, 250, 255)]
def recognition(image, moxing):
    start_time = time.time()  # 计时开始

    moxingstr = "model/" + moxing + '/' + 'PCC.pt'
    model = YOLO(moxingstr)
    

    # device = torch.device('cuda') if torch.cuda.is_available() else torch.device('cpu')

    pred_list=[]
    results = model.predict(image, augment=False,conf=0.05)
    
    print("CUDA available:", torch.cuda.is_available())
    print("Current device:", torch.device("cuda" if torch.cuda.is_available() else "cpu"))
    names = results[0].names

    for result in results:
        boxes = result.boxes
        class_list = boxes.cls.cpu().tolist()
        if class_list:
            masks = result.masks.xy
            for index, item in enumerate(class_list):
                pred_list.append({
                    'label': names[item],
                    'points': crop_image_by_pixels(image, masks[index].tolist()),
                    "mask": masks[index].tolist()
                })

    # 计时结束
    cost = time.time() - start_time
    print(f"[recognition-{moxing}] 耗时：{cost:.4f} 秒")

    return pred_list

def main(img_path, index):
    start_time = time.time()  # 开始计时

    first_predictions = []
    second_predictions = {}
    thirdly_predictions = {}
    data = []

    if index == 0:
        neirong = recognition(img_path, 'part')

        for item in neirong:
            if item['label'] == 'head':
                head = item['mask']
                break
        else:
            head = []

        neirong2 = recognition(img_path, 'head_feature')
        head_feature = neirong2[0]['mask'] if neirong2 else []

        cost = time.time() - start_time
        print(f"[main-0] 整体耗时：{cost:.4f} 秒")

        return {'head': head, 'head_feature': head_feature}

    elif index == 1:
        neirong = recognition(img_path, 'part')
        for item in neirong:
            if item['label'] == 'limb-after-l':
                if 'limb-after-l' not in second_predictions:
                    second_predictions['limb-after-l'] = item['points']
                    biezhen = recognition(second_predictions['limb-after-l'], 'limb-feature')
                    if biezhen:
                        data.append('after-l' + '-' + biezhen[0]['label'][-2:])

            elif item['label'] == 'limb-front-l':
                if 'limb-front-l' not in second_predictions:
                    second_predictions['limb-front-l'] = item['points']
                    biezhen2 = recognition(second_predictions['limb-front-l'], 'limb-feature')
                    if biezhen2:
                        data.append('front-l' + '-' + biezhen2[0]['label'][-2:])

    elif index == 2:
        neirong = recognition(img_path, 'part')
        for item in neirong:
            if item['label'] == 'limb-after-r':
                if 'limb-after-r' not in thirdly_predictions:
                    thirdly_predictions['limb-after-r'] = item['points']
                    biezhen = recognition(thirdly_predictions['limb-after-r'], 'limb-feature')
                    if biezhen:
                        data.append('after-r' + '-' + biezhen[0]['label'][-2:])

            elif item['label'] == 'limb-front-r':
                if 'limb-front-r' not in thirdly_predictions:
                    thirdly_predictions['limb-front-r'] = item['points']
                    biezhen2 = recognition(thirdly_predictions['limb-front-r'], 'limb-feature')
                    if biezhen2:
                        data.append('front-r' + '-' + biezhen2[0]['label'][-2:])

    cost = time.time() - start_time
    print(f"[main-{index}] 整体耗时：{cost:.4f} 秒")

    return data

def calculate_width_height(data):
    # print(data)
    x_coords = [point[0] for point in data]
    y_coords = [point[1] for point in data]
    width = max(x_coords) - min(x_coords)
    height = max(y_coords) - min(y_coords)
    return width, height
import numpy as np
def resize_pixel_array(pixel_array, scale_factor):
    new_pixel_array = []
    for i in range(len(pixel_array)):
        new_point = [pixel_array[i][0] / scale_factor, pixel_array[i][1] / scale_factor]
        new_pixel_array.append(new_point)
    return new_pixel_array
def calculate_distance_between_rectangles(pixel_array1, pixel_array2,scale_factor):
    x1_min = min(pixel[0] for pixel in pixel_array1)
    y1_min = min(pixel[1] for pixel in pixel_array1)
    x2_min = min(pixel[0] for pixel in pixel_array2)
    y2_min = min(pixel[1] for pixel in pixel_array2)
    x_distance = abs(x1_min - x2_min)/scale_factor
    y_distance = abs(y1_min - y2_min)/scale_factor
    return x_distance, y_distance
def overlay_pixel_region(image_path, pixel_array, x, y,x_fact,y_fact):
    # 打开图片
    img = Image.open(image_path)

    # 创建一个不带透明通道的 RGB 拷贝
    img_rgb = img.convert("RGB")
    draw = ImageDraw.Draw(img_rgb)

    # 计算外接矩形的左上角坐标和右下角坐标
    x_min = min(pixel[0] for pixel in pixel_array)
    y_min = min(pixel[1] for pixel in pixel_array)
    # x_max = max(pixel[0] for pixel in pixel_array)
    # y_max = max(pixel[1] for pixel in pixel_array)
    # 计算偏移量
    offset_x = x - x_min
    offset_y = y - y_min
    # 调整所有像素的坐标
    # 调整所有像素的坐标
    adjusted_pixel_array = [[pixel[0] + offset_x + x_fact, pixel[1] + offset_y + y_fact] for pixel in pixel_array]
    # 将调整后的像素数组转换为坐标列表
    point_list = [tuple(pixel) for pixel in adjusted_pixel_array]
    # 绘制红色多边形填充
    draw.polygon(point_list, outline="red", fill="red")
    return img_rgb
# 打印合并后的所有点
def overlay_pixel_region2(img, pixel_array):
    # 创建一个不带透明通道的 RGB 拷贝
    img_rgb = img.convert("RGB")
    draw = ImageDraw.Draw(img_rgb)
    for list in pixel_array:
        adjusted_pixel_array = [[pixel[0] , pixel[1] ] for pixel in list]
        # 将调整后的像素数组转换为坐标列表
        point_list = [tuple(pixel) for pixel in list]
        # 绘制红色多边形填充
        draw.polygon(point_list, outline="red", fill="red")
    # 保存修改后的图片
    img_rgb.save("output_1.jpg")
